mapper.select:
SELECT a.id, b.id as riskSourceId, b.serial_number, b.`name`, b.type_name, b.area_id, b.bim_code, b.type_code FROM `risk_source_bim_config` a INNER JOIN risk_source_ledger b ON a.business_id = b.id
a.scene_type=#{param.sceneType}
and b.type_code=#{param.typeCode}
and b.area_id like CONCAT('%',#{param.areaId},'%')
and (b.`name` like CONCAT('%',#{param.keyword},'%') or b.`serial_number` like CONCAT('%',#{param.keyword},'%'))
order by b.create_time desc

SELECT a.id, b.scene_type FROM risk_source_ledger a left join risk_source_bim_config b on a.id = b.business_id and b.scene_type = #{param.sceneType} where scene_type is null
and a.type_code=#{param.typeCode}
and (a.`name` like CONCAT('%',#{param.keyword},'%') or a.`serial_number` like CONCAT('%',#{param.keyword},'%'))
